int _workoutLogEstimateSize(
  WorkoutLog object,
  List<int> offsets,
  Map<Type, List<int>> allOffsets,
) {
  var bytesCount = offsets.last;
  bytesCount += 3 + object.bodyPart.length * 3;
  bytesCount += 3 + object.dateKey.length * 3;
  bytesCount += 3 + object.exerciseName.length * 3;
  bytesCount += 3 + object.notes.length * 3;
  return bytesCount;
}

void _workoutLogSerialize(
  WorkoutLog object,
  IsarWriter writer,
  List<int> offsets,
  Map<Type, List<int>> allOffsets,
) {
  writer.writeString(offsets[0], object.bodyPart);
  writer.writeString(offsets[1], object.dateKey);
  writer.writeDouble(offsets[2], object.duration);
  writer.writeString(offsets[3], object.exerciseName);
  writer.writeString(offsets[4], object.notes);
  writer.writeLong(offsets[5], object.reps);
  writer.writeLong(offsets[6], object.sets);
  writer.writeDateTime(offsets[7], object.timestamp);
  writer.writeDouble(offsets[8], object.weight);
}

WorkoutLog _workoutLogDeserialize(
  Id id,
  IsarReader reader,
  List<int> offsets,
  Map<Type, List<int>> allOffsets,
) {
  final object = WorkoutLog();
  object.bodyPart = reader.readString(offsets[0]);
  object.dateKey = reader.readString(offsets[1]);
  object.duration = reader.readDouble(offsets[2]);
  object.exerciseName = reader.readString(offsets[3]);
  object.id = id;
  object.notes = reader.readString(offsets[4]);
  object.reps = reader.readLong(offsets[5]);
  object.sets = reader.readLong(offsets[6]);
  object.timestamp = reader.readDateTime(offsets[7]);
  object.weight = reader.readDouble(offsets[8]);
  return object;
}

